/**
 * Pure utility functions for log level filtering.
 * Exposed separately to facilitate easy unit testing without class instantiation.
 */

const LOG_LEVELS = {
  DEBUG: 0,
  INFO: 1,
  WARN: 2,
  ERROR: 3
};

/**
 * Checks if a given log level should be output based on the current threshold.
 * @param {string} messageLevel - The level of the message being logged (e.g., 'DEBUG')
 * @param {string} currentLevel - The configured threshold level (e.g., 'INFO')
 * @returns {boolean} True if the message should be logged, false otherwise.
 */
export function isLoggable(messageLevel, currentLevel) {
  const messageWeight = LOG_LEVELS[messageLevel];
  const currentWeight = LOG_LEVELS[currentLevel];

  // If either level is invalid, default to false to be safe
  if (messageWeight === undefined || currentWeight === undefined) {
    return false;
  }

  return messageWeight >= currentWeight;
}

export default isLoggable;
```

